fn protocol_version_is_supported(version: &str) -> bool {
    version == MCP_PROTOCOL_VERSION || version == MCP_COMPATIBLE_PROTOCOL_VERSION
}

fn negotiated_protocol_version(object: &serde_json::Map<String, Value>) -> &str {
    object
        .get("params")
        .and_then(Value::as_object)
        .and_then(|params| params.get("protocolVersion"))
        .and_then(Value::as_str)
        .filter(|version| protocol_version_is_supported(version))
        .unwrap_or(MCP_PROTOCOL_VERSION)
}

